
let engineHTML=new TextDecoder().decode(Uint8Array.from(atob(''),c=>c.charCodeAt(0)));
engineHTML=engineHTML.replace('</style>','.diagnostics{display:none!important}</style>');
// Report the CURRENT Line Clear block count, not the lowest count ever seen.
// The previous historical minimum could show 7 while 13+ blocks were visible
