const bpLineOldCounter="if(bpLineLowestRemaining===null)bpLineLowestRemaining=rawRemaining;\\n else bpLineLowestRemaining=Math.min(bpLineLowestRemaining,rawRemaining);\\n return {remaining:bpLineLowestRemaining,";
const bpLineCurrentCounter="return {remaining:rawRemaining,";
engineHTML=engineHTML.replace(
 /if\(bpLineLowestRemaining===null\)bpLineLowestRemaining=rawRemaining;\s*else bpLineLowestRemaining=Math\.min\(bpLineLowestRemaining,rawRemaining\);\s*return \{remaining:bpLineLowestRemaining,/,
 bpLineCurrentCounter
);

const $=id=>document.getElementById(id);let isVersus=false,started=false,ready=new Set(),settings=null,scores={human:0,cpu:0},ended={};
// Non-campaign Versus Line Clear diagnostics; never used for campaign scoring.
const bpVLineKey='bp-versus-line-diagnostics-v1';
let bpVLineHistory=[];try{bpVLineHistory=JSON.parse(localStorage.getItem(bpVLineKey)||'[]');if(!Array.isArray(bpVLineHistory))bpVLineHistory=[]}catch(e){bpVLineHistory=[]}
let bpVLineCurrent=null,bpVLineLastSamples={human:null,cpu:null};
function bpVLineEnabled(){return !bpCampaignSettings&&isVersus&&settings?.mode==='line'}
function bpVLinePersist(){try{localStorage.setItem(bpVLineKey,JSON.stringify(bpVLineHistory))}catch(e){console.warn('Diagnostics local storage unavailable',e)}}
function bpVLineDisplay(){
 const el=$('bpVLineDiag');if(!el)return;
 el.hidden=!bpVLineEnabled();if(el.hidden)return;
 const h=bpVLineLastSamples.human,c=bpVLineLastSamples.cpu;
 $('bpVLineLive').textContent='CPU: '+(c?.remaining??'—')+' blocks above line · You: '+(h?.remaining??'—')+' · CPU '+(settings?.aiDifficulty||'—');
 const last=bpVLineHistory.at(-1);
 $('bpVLineLast').textContent=last?'Last: '+last.winner+' · CPU remaining '+(last.cpuRemaining??'—')+' · '+Math.round(last.elapsedMs/1000)+'s':'';
 $('bpVLineCount').textContent=bpVLineHistory.length+' recorded matches · non-campaign only';
}
function bpVLineBegin(){
 bpVLineLastSamples={human:null,cpu:null};bpVLineCurrent=bpVLineEnabled()?{
  startedAt:new Date().toISOString(),difficulty:settings.difficulty,cpuDifficulty:settings.aiDifficulty,
  openingSeed:settings.openingSeed,mode:'versus-line',samples:[],initialHuman:null,initialCpu:null
 }:null;bpVLineDisplay();
}
function bpVLineSample(d){
 if(!bpVLineCurrent||!bpVLineEnabled()||!d.lineMeasure||!['human','cpu'].includes(d.who))return;
 const x=d.lineMeasure;const item={remaining:x.remaining,occupied:x.occupied,targetRow:x.targetRow,elapsedMs:x.elapsedMs,score:Number(d.score)||0};
 bpVLineLastSamples[d.who]=item;
 if(d.who==='human'&&!bpVLineCurrent.initialHuman)bpVLineCurrent.initialHuman=item;
 if(d.who==='cpu'&&!bpVLineCurrent.initialCpu)bpVLineCurrent.initialCpu=item;
 if(!bpVLineCurrent.samples.length||Math.floor(x.elapsedMs/15000)>Math.floor(bpVLineCurrent.samples.at(-1).elapsedMs/15000)){
  bpVLineCurrent.samples.push({elapsedMs:x.elapsedMs,human:bpVLineLastSamples.human,cpu:bpVLineLastSamples.cpu});
 }
 bpVLineDisplay();
}
function bpVLineFinish(winner){
 if(!bpVLineCurrent||!bpVLineEnabled())return;
 const h=bpVLineLastSamples.human,c=bpVLineLastSamples.cpu;
 const rec={...bpVLineCurrent,endedAt:new Date().toISOString(),winner,
  elapsedMs:Math.max(h?.elapsedMs||0,c?.elapsedMs||0),
  humanRemaining:h?.remaining??null,cpuRemaining:c?.remaining??null,
  humanOccupied:h?.occupied??null,cpuOccupied:c?.occupied??null,
  humanScore:scores.human,cpuScore:scores.cpu};
 bpVLineHistory.push(rec);bpVLinePersist();bpVLineCurrent=null;bpVLineDisplay();
}
function bpVLineDownload(type){
 const records=bpVLineHistory;
 const columns=['startedAt','endedAt','difficulty','cpuDifficulty','openingSeed','winner','elapsedMs','humanRemaining','cpuRemaining','humanOccupied','cpuOccupied','humanScore','cpuScore','initialHumanRemaining','initialCpuRemaining'];
 const flat=records.map(r=>({...r,initialHumanRemaining:r.initialHuman?.remaining??'',initialCpuRemaining:r.initialCpu?.remaining??''}));
 const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
 const content=type==='json'?JSON.stringify(records,null,2):[columns.join(','),...flat.map(r=>columns.map(k=>quote(r[k])).join(','))].join('\r\n');
 const blob=new Blob([content],{type:type==='json'?'application/json':'text/csv'});
 const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Block-Party-Versus-Line-Diagnostics.'+type;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);
}
$('bpVLineExport').onclick=()=>bpVLineDownload('csv');$('bpVLineJSON').onclick=()=>bpVLineDownload('json');
$('bpVLineClear').onclick=()=>{if(confirm('Clear all locally saved Versus Line Clear diagnostics?')){bpVLineHistory=[];bpVLinePersist();bpVLineDisplay()}};

function explain(){
 const play=$('play').value, modeSelect=$('mode');
 // Keep the game choices specific to the selected play style.
 const unlimited=modeSelect.querySelector('[value="unlimited"]');
 const battle=modeSelect.querySelector('[value="battle"]');
 unlimited.hidden=unlimited.disabled=play==='versus';
 battle.hidden=battle.disabled=play!=='versus';
 if(play==='versus'&&modeSelect.value==='unlimited')modeSelect.value='battle';
 if(play==='solo'&&modeSelect.value==='battle')modeSelect.value='unlimited';
 const mode=modeSelect.value;const superEasy=$('diff').querySelector('[value="super-easy"]');const allowed=play==='solo'&&mode==='line';superEasy.disabled=!allowed;superEasy.hidden=!allowed;if(!allowed&&$('diff').value==='super-easy')$('diff').value='easy';$('cpuDifficultyField').hidden=play!=='versus';$('timeLabel').hidden=$('duration').hidden=$('durationButtons').hidden=mode!=='timed';$('explain').textContent=play==='versus'?'Outlast the computer. Use matches and special blocks to win!':mode==='line'?($('diff').value==='super-easy'?'Practice Mode — manual row raising, no global leaderboard scores.':'Clear the target line as quickly as you can.'):mode==='timed'?'Race the clock and score as many points as possible.':'Keep matching and survive as long as you can.'}

// Buttons are the visible menu UI; original selects remain the single source of truth.
const bpTouched=new Set();
let bpPlayChosen=false;
function bpSelectionReady(){
 const play=$('play').value,mode=$('mode').value;
 return bpPlayChosen && bpTouched.has('mode') && bpTouched.has('diff') &&
   (play!=='versus' || bpTouched.has('aiDiff')) &&
   (mode!=='timed' || bpTouched.has('duration'));
}
function bpUpdateStartAvailability(){
 const btn=$('start'),ready=bpSelectionReady();
 btn.disabled=!ready;
 btn.setAttribute('aria-disabled',String(!ready));
 btn.title=ready?'Start selected game':'Choose a play style, game mode, and required options first';
 const cost=btn.querySelector(".bp-entry-cost");if(cost)cost.textContent=($("play").value==="solo" && $("mode").value==="line" && $("diff").value==="super-easy")?"FREE":"🪙 2";
 const note=document.querySelector('.launch-footnote');
 if(note)note.textContent=ready?'READY, SET, MATCH!':'SELECT A GAME AND OPTIONS TO START';
}

const bpNames={mode:{line:'Line Clear',timed:'Timed Play',unlimited:'Unlimited',battle:'Special Battle'},diff:{'super-easy':'Practice',easy:'Easy',medium:'Medium',hard:'Hard'},aiDiff:{easy:'Easy',medium:'Medium',hard:'Hard','super-hard':'Super Hard'},duration:{90:'90 sec',180:'3 min',300:'5 min'}};
function bpControlDiagram(side){
 const pad='<span class="blank"></span><span>▲</span><span class="blank"></span><span>◀</span><span>◆</span><span>▶</span><span class="blank"></span><span>▼</span><span class="blank"></span>';
 const a='<span>RAISE</span><span>SWAP</span>';
 const padEl='<span class="bp-mini-pad">'+pad+'</span>',actEl='<span class="bp-mini-actions">'+a+'</span>';
 return '<span class="bp-control-diagram">'+(side==='left'?padEl+actEl:actEl+padEl)+'</span>';
}
function bpShowSettings(){
 const visible=bpTouched.has('mode');
 $('arcadeSettings').hidden=!visible;
}
function bpRenderChoices(){
 for(const id of ['mode','diff','aiDiff','duration','controlSideMenu']){
  const select=$(id),container=$(id+'Buttons');if(!container)continue;
  const opts=Array.from(select.options).filter(o=>!o.hidden&&!o.disabled);
  const old=new Map(Array.from(container.children).map(b=>[b.dataset.value,b]));
  for(const opt of opts){
   let b=old.get(opt.value);
   if(!b){
    b=document.createElement('button');b.type='button';b.className='bp-choice';b.dataset.value=opt.value;
    if(id==='controlSideMenu'){b.innerHTML=bpControlDiagram(opt.value);b.setAttribute('aria-label',opt.textContent)}
    else {b.textContent=bpNames[id]?.[opt.value]||opt.textContent;
     if(id==='aiDiff'){const sub=document.createElement('small');sub.className='bp-choice-sub';sub.textContent=({easy:'1.25s',medium:'0.75s',hard:'0.50s','super-hard':'0.25s'})[opt.value];b.appendChild(sub)}}
    b.addEventListener('click',()=>{select.value=b.dataset.value;bpTouched.add(id);if(id==='mode')bpShowSettings();select.dispatchEvent(new Event('change',{bubbles:true}));bpRenderChoices();bpUpdateStartAvailability()});
   }
   const active=bpTouched.has(id)&&select.value===opt.value;
   b.classList.toggle('is-selected',active);b.setAttribute('aria-pressed',String(active));
   container.appendChild(b);old.delete(opt.value);
  }
  old.forEach(b=>b.remove());
  // Fractional tracks account for spacing while keeping the entire row at 100%.
  // Reuse the button nodes so the browser can animate widths between selections.
  const count=opts.length,chosen=opts.findIndex(o=>bpTouched.has(id)&&o.value===select.value);
  const weights=opts.map((_,i)=>chosen<0?1:(i===chosen?(count===2?60:40):(count===2?40:count===3?30:20)));
  container.style.gridTemplateColumns=weights.map(w=>w+'fr').join(' ');
 }
}
