document.querySelectorAll('#menu .play-tile').forEach(b=>b.addEventListener('click',()=>{bpPlayChosen=true;$('play').value=b.dataset.play;bpTouched.delete('mode');bpTouched.delete('diff');bpTouched.delete('aiDiff');bpTouched.delete('duration');explain();syncPlayTiles();bpShowSettings();bpRenderChoices();bpUpdateStartAvailability();}));
$('play').addEventListener('change',syncPlayTiles);explain();syncPlayTiles();bpShowSettings();bpRenderChoices();bpUpdateStartAvailability();
function tell(who,msg){const f=$(who);if(f&&f.contentWindow)f.contentWindow.postMessage(msg,'*')}
function layoutGame(){
 if(!started)return;
 const arena=$('arena'),vw=innerWidth,vh=innerHeight;
 const top=$('top').getBoundingClientRect().height;
 // Compact left-aligned D-pad: preserve the full four-way layout without oversized controls.
 const padWidth=Math.min(vw-12,580)*.70-8;
 const padCell=Math.max(54,Math.min(88,Math.floor((padWidth-8)/3),Math.floor(vh*.105)));
 const padHeight=Math.max(220,Math.min(290,Math.round(vh*.29)));
 arena.style.setProperty('--pad-cell',padCell+'px');
 arena.style.setProperty('--raise-height',Math.max(45,Math.floor(padCell*.95))+'px');
 if(isVersus){
   // Fit two complete boards and the controls in the viewport. Shrink board
   // WIDTH and HEIGHT together rather than clipping the last few rows.
   const available=Math.max(250,vh-top-padHeight-54);
   const zoneWidth=Math.max(105,Math.min((Math.min(vw,760)-28)/2,(available-26)/2));
   arena.style.setProperty('--versus-zone-width',Math.floor(zoneWidth)+'px');
   arena.style.setProperty('--versus-iframe-height',Math.floor(zoneWidth*2+5)+'px');
   arena.style.setProperty('--versus-controls-gap','9px');
   return;
 }
 const side=Math.max(78,Math.min(108,Math.round(vw*.22)));
 // Match the Versus iframe height exactly, using the SAME calculation.
 // The Solo board must be resized as a whole, not cropped at its bottom.
 const versusAvailable=Math.max(250,vh-top-padHeight-54);
 const versusZoneWidth=Math.max(105,Math.min((Math.min(vw,760)-28)/2,(versusAvailable-26)/2));
 // Give Solo 30px more height than the Versus-sized baseline, scaling width
 // proportionally so the complete 6x12 grid remains visible.
 const boardHeight=Math.floor(versusZoneWidth*2+5)+30;
 const boardWidth=Math.floor((boardHeight-5)/2);
 arena.style.setProperty('--solo-board-width',boardWidth+'px');
 arena.style.setProperty('--solo-board-height',boardHeight+'px');
 // Force the actual Solo frame and iframe to use the same dimensions.
 // Inline important rules beat legacy fixed-size selectors and prevent clipped rows.
 const soloZone=$('humanZone'),soloFrame=$('human');
 for(const el of [soloZone,soloFrame]){
   el.style.setProperty('width',boardWidth+'px','important');
   el.style.setProperty('height',boardHeight+'px','important');
   el.style.setProperty('max-height',boardHeight+'px','important');
   el.style.setProperty('min-height','0','important');
 }
 soloZone.style.setProperty('flex','0 0 '+boardWidth+'px','important');
 soloFrame.style.setProperty('aspect-ratio','auto','important');
 arena.style.setProperty('--solo-hud-width',side+'px');
 arena.style.setProperty('--control-gap','9px');
 requestAnimationFrame(bpPositionSoloGoal);
}
window.addEventListener('resize',()=>{layoutGame();positionMiniLeaderboard()});
function bpPositionSoloGoal(){
 const goal=$('soloGoal')?.closest('.hud-card');
 const boards=$('boards'),board=$('humanZone');
 if(!goal||!boards||!board)return;
 if(isVersus||$('arena').hidden){goal.style.removeProperty('position');goal.style.removeProperty('left');goal.style.removeProperty('top');goal.style.removeProperty('width');return;}
 const host=boards.getBoundingClientRect(),rect=board.getBoundingClientRect();
 const space=Math.max(64,innerWidth-rect.right-12);
 goal.style.setProperty('position','absolute','important');
 goal.style.setProperty('left',Math.round(rect.right-host.left+6)+'px','important');
 goal.style.setProperty('top','0px','important');
 goal.style.setProperty('width',Math.min(108,space-6)+'px','important');
 goal.style.setProperty('box-sizing','border-box','important');
}
window.addEventListener('resize',()=>requestAnimationFrame(bpPositionSoloGoal));


