let bpPlayer='',bpMiniPeriod=0,bpMiniShowScore=false,bpMiniTimer=null,bpMiniCache={},bpMiniGeneration=0;
async function bpRpc(name,payload){
 const response=await fetch(BP_SUPABASE_URL+'/rest/v1/rpc/'+name,{method:'POST',headers:{'Content-Type':'application/json','apikey':BP_SUPABASE_KEY,'Authorization':'Bearer '+BP_SUPABASE_KEY},body:JSON.stringify(payload)});
 if(!response.ok){const detail=await response.text();throw Error('Leaderboard service: '+response.status+' '+detail.slice(0,160))}
 return response.json();
}
function bpMode(){return isVersus?'versus-'+(settings?.difficulty||'medium'):settings?.mode==='timed'?'timed-'+settings.duration:settings?.mode||'line'}
function bpDifficulty(){return isVersus?settings?.aiDifficulty||'medium':settings?.difficulty||'easy'}
function bpEscape(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function bpTime(ms){if(ms==null||!Number.isFinite(Number(ms)))return '—';let sec=Math.round(Number(ms)/10)/100;return Math.floor(sec/60)+':'+String(Math.floor(sec%60)).padStart(2,'0')+'.'+String(Math.round(sec*100)%100).padStart(2,'0')}
const BP_LB_MODES=[['line','Line Clear'],['timed-90','Timed Play · 90s'],['timed-180','Timed Play · 3m'],['timed-300','Timed Play · 5m'],['unlimited','Unlimited Play']];
const BP_LB_DIFFICULTIES=[['easy','Easy'],['medium','Medium'],['hard','Hard']];
const BP_LB_PERIODS=[['day','Daily'],['week','Weekly'],['month','Monthly'],['all','All-Time']];
let bpLbModeIndex=0,bpLbDifficulty='easy',bpLbPeriod='all',bpLbRequest=0;
function bpEntryHtml(items,mini=false,showScore=false,mode=''){
 if(!items.length)return '<div style="padding:20px 2px;color:#b8a9d5;text-align:center">No scores yet</div>';
 return items.map((x,i)=>'<div class="bp-entry"><span>'+(i+1)+'.</span><span>'+(mini?(showScore?(mode==='line'?bpTime(x.duration_ms):Number(x.score).toLocaleString()):bpEscape(x.player_name)):'<b>'+bpEscape(x.player_name)+'</b><small>'+new Date(x.achieved_at).toLocaleString()+'</small>')+'</span>'+(mini?'':'<strong>'+(mode==='line'?bpTime(x.duration_ms)+'<small>'+Number(x.score).toLocaleString()+' pts</small>':Number(x.score).toLocaleString())+'</strong>')+'</div>').join('');
}
