function bpRankRender({mode,difficulty,score,elapsedMs,all,placements,when}){
 const ranks=Object.fromEntries(placements),allTime=ranks.all||null;
 const best=placements.length?Math.min(...placements.map(x=>x[1])):null;
 const headline=allTime===1?'GLOBAL CHAMPION!':allTime!=null&&allTime<=3?'TOP 3 FINISH!':allTime!=null?'GLOBAL TOP 10!':ranks.day===1?'NEW DAILY RECORD!':best!=null?'TOP 10 FINISH!':'GAME COMPLETE!';
 const isLine=mode==='line',label=BP_LB_MODES.find(x=>x[0]===mode)?.[1]||mode;
 const difficultyLabel=BP_LB_DIFFICULTIES.find(x=>x[0]===difficulty)?.[1]||difficulty;
 const root=$('bpHighScore');root.classList.toggle('bp-rank-first',allTime===1);
 $('bpRankHeadline').textContent=headline;
 $('bpRankEmblem').textContent=allTime===1?'🏆✨':allTime!=null&&allTime<=3?'🥇✨':best!=null?'🏅✨':'🎮✨';
 $('bpRankMode').textContent=(label+' · '+difficultyLabel).toUpperCase();
 $('bpRankMetricLabel').textContent=isLine?'YOUR FINISH TIME':'YOUR FINAL SCORE';
 $('bpRankMetric').textContent=isLine?bpTime(elapsedMs):Math.floor(score).toLocaleString();
 $('bpRankSecondary').textContent=isLine?Math.floor(score).toLocaleString()+' POINTS':bpEscape(bpPlayer);
 $('bpRankBadges').innerHTML=BP_LB_PERIODS.map(([key,label],i)=>'<div class="bp-rank-badge '+(ranks[key]?'':'missed')+'" style="animation-delay:'+(i*.11)+'s"><span>'+label.toUpperCase()+'</span><strong>'+(ranks[key]?'#'+ranks[key]:'—')+'</strong></div>').join('');
 // Show the All-Time board when ranked there, otherwise the player's best qualifying period.
 const chosen=ranks.all?'all':placements.length?['day','week','month','all'].find(p=>ranks[p]===best)||placements[0][0]:'all';
 const periodLabel=BP_LB_PERIODS.find(x=>x[0]===chosen)?.[1]||'All-Time';
 $('bpRankBoardPeriod').textContent=periodLabel.toUpperCase();
 const rows=all[BP_PERIODS.indexOf(chosen)]||[];
 const matched=rows.findIndex(x=>bpRankIsOwnEntry(x,score,elapsedMs,when,mode));
 $('bpRankBoard').innerHTML=rows.length?rows.map((x,i)=>'<div class="bp-rank-row '+(i===matched?'mine':'')+'" style="animation-delay:'+(Math.min(i,9)*.07+.18)+'s"><span class="bp-rank-position">'+(i===0?'👑':(i+1)+'.')+'</span><strong>'+bpEscape(x.player_name)+(i===matched?' ✦':'')+'</strong><span class="bp-rank-value">'+(isLine?bpTime(x.duration_ms):Number(x.score).toLocaleString())+'</span></div>').join(''):'<div class="bp-rank-empty">No scores in this period yet.</div>';
 $('bpRankFootnote').textContent=best!=null?'Your highlighted entry shows where you stand against other players.':'Your score was saved. Keep playing to reach the Top 10!';
 root.hidden=false;
}
function bpRankIsOwnEntry(x,score,elapsedMs,when,mode){
 return x.player_name===bpPlayer&&Number(x.score)===Math.floor(score)&&
 (mode!=='line'||Math.abs(Number(x.duration_ms)-Math.round(elapsedMs))<=20)&&
 Math.abs(new Date(x.achieved_at).getTime()-when)<120000;
}
async function submitCompletedScore(score,elapsedMs=null){
 if(isVersus||bpDifficulty()==='super-easy'||bpDifficulty()==='practice')return;
 if(!bpPlayer||!Number.isFinite(score)||score<0)return;
 const mode=bpMode(),difficulty=bpDifficulty(),when=Date.now();
 try{
  await bpRpc('submit_leaderboard_score',{p_player_name:bpPlayer,p_game_mode:mode,p_difficulty:difficulty,p_score:Math.floor(score),p_client_id:bpClientId(),p_duration_ms:elapsedMs==null?null:Math.round(elapsedMs)});
  const all=await Promise.all(BP_PERIODS.map(p=>bpGetScores(mode,difficulty,p)));
  const placements=[];
  for(let i=0;i<all.length;i++){
   const place=all[i].findIndex(x=>bpRankIsOwnEntry(x,score,elapsedMs,when,mode));
   if(place>=0)placements.push([BP_PERIODS[i],place+1]);
  }
  bpRankRender({mode,difficulty,score,elapsedMs,all,placements,when});
  bpMiniCache={};
 }catch(e){console.warn('Score could not be submitted:',e);$('message').textContent='Score not uploaded — '+e.message.slice(0,65)}
}
