const bpAttackFx=document.createElement('div');bpAttackFx.id='bpAttackFx';bpAttackFx.setAttribute('aria-hidden','true');document.body.appendChild(bpAttackFx);
function bpAnimateAttack(d){
 if(!started||!isVersus||settings?.mode!=='unlimited'||d.kind==='negative')return 0;
 const source=document.getElementById(d.from==='cpu'?'cpu':'human');
 const dest=document.getElementById(d.from==='cpu'?'human':'cpu');
 if(!source||!dest)return 0;
 const a=source.getBoundingClientRect(),b=dest.getBoundingClientRect();
 if(!a.width||!b.width)return 0;
 const ox=Math.max(0,Math.min(360,Number(d.origin?.x)||180));
 const oy=Math.max(0,Math.min(720,Number(d.origin?.y)||360));
 const sx=a.left+a.width*ox/360,sy=a.top+a.height*oy/720;
 const tx=b.left+b.width*.5,ty=b.top+Math.min(18,b.height*.08);
 const colors=d.kind==='rainbow'?['#ff5fa7','#ffce5d','#62e5ff','#9e77ff','#70ffad']:['#67d8ff','#ffd47c','#ed70ff'];
 const count=Math.min(34,Math.max(12,12+Math.round(Math.min(8,Number(d.count)||1)*2)));
 for(let i=0;i<count;i++){
  const dot=document.createElement('i');dot.className='bp-attack-particle';
  const spread=(i%7-3)*5;const endSpread=(i%9-4)*4;
  dot.style.setProperty('--sx',(sx+spread)+'px');dot.style.setProperty('--sy',(sy+(i%5-2)*5)+'px');
  dot.style.setProperty('--ex',(tx+endSpread)+'px');dot.style.setProperty('--ey',(ty+(i%4-2)*4)+'px');
  dot.style.setProperty('--sz',(9+i%5*2.8)+'px');dot.style.setProperty('--hue',colors[i%colors.length]);
  dot.style.setProperty('--delay',(i%10*28)+'ms');dot.style.setProperty('--dur',(790+i%6*90)+'ms');
  bpAttackFx.appendChild(dot);setTimeout(()=>dot.remove(),1800);
 }
 return count;
}

const bpPoisonLog=[];let bpDiagSeq=0;
function bpAuditReport(){
 const matches=bpPoisonLog.filter(e=>e.event==='match-audit');
 const created=bpPoisonLog.filter(e=>e.event==='attack-created');
 const routed=bpPoisonLog.filter(e=>e.event==='attack-routed');
 const garbage=bpPoisonLog.filter(e=>e.event==='garbage-created');
 const issues=[];
 const particles=bpPoisonLog.filter(e=>e.event==='particle-generated');
 for(const attack of routed){
  const id=attack.audit?.attackId;
  if(id&&attack.kind!=='negative'&&attack.kind!=='rainbow'&&!particles.some(p=>p.who===attack.who&&p.details?.attackId===id&&p.details?.particleCount>0))
   issues.push({severity:'mismatch',who:attack.who,issue:'Attack routed without particles',attackId:id});
 }
 for(const p of particles){
  const id=p.details?.attackId;
  if(p.details?.particleCount>0&&(!id||!routed.some(a=>a.who===p.who&&a.audit?.attackId===id)))
   issues.push({severity:'mismatch',who:p.who,issue:'Particles without corresponding routed attack',attackId:id});
 }
 for(const match of matches){
  const expected=match.details?.expectedComboAttacks||[];
  const actual=created.filter(e=>e.who===match.who&&e.details?.audit?.matchEvent===match.details?.event&&e.details?.kind==='comboGarbage');
  const counts=a=>a.map(x=>x.count).sort((a,b)=>a-b);
  const a=counts(actual.map(x=>x.details)),b=counts(expected);
  if(JSON.stringify(a)!==JSON.stringify(b))issues.push({severity:'mismatch',who:match.who,matchEvent:match.details?.event,
    issue:'Combo garbage does not match qualifying 4+ normal-color groups',expected:b,actual:a});
 }
 for(const attack of created){
  const d=attack.details||{};
  if(d.kind==='comboGarbage'&&!matches.some(e=>e.who===attack.who&&e.details?.event===d.audit?.matchEvent))
   issues.push({severity:'unverified',who:attack.who,issue:'Combo attack has no corresponding match-audit event',attack:d});
  if(d.kind==='rainbow'&&!['completed-gravity-chain','gravity-chain-stage'].includes(d.audit?.reason))
   issues.push({severity:'unverified',who:attack.who,issue:'Rainbow attack has no completed-chain provenance',attack:d});
 }
 return {rules:{combo:'Each distinct normal-color match group with at least 4 tiles sends one width-4-to-6 slab',
  chain:'Each newly reached gravity-chain depth immediately sends only newly earned rows; parallel branches add zero',
  exclusions:'Independent 3-matches do not qualify for combo garbage; poison and special effects have separate rules'},
  summary:{matches:matches.length,attacksCreated:created.length,attacksRouted:routed.length,garbageCreated:garbage.length,particlesGenerated:particles.length,
    issues:issues.length,bySide:{human:{matches:matches.filter(e=>e.who==='human').length,attacks:created.filter(e=>e.who==='human').length},
    cpu:{matches:matches.filter(e=>e.who==='cpu').length,attacks:created.filter(e=>e.who==='cpu').length}}},
  issues,limitations:['Audit checks combo attribution and records chain provenance, but does not independently replay the physics engine.',
   'Special effects, poison penalties, and garbage landings require separate causal interpretation.']};
}

$('bpDiagExport').onclick=()=>{const data={version:'2.1.00',exported:new Date().toISOString(),audit:bpAuditReport(),directionalAmbiguityAudit:bpAmbiguitySummary(),inputAudit:{touches:bpPoisonLog.filter(e=>e.event==='touch-down').length,missesInControls:bpPoisonLog.filter(e=>e.event==='touch-down'&&e.details?.status==='miss').length,commands:bpPoisonLog.filter(e=>e.event==='control-command').length,recoveredNearMisses:bpPoisonLog.filter(e=>e.event==='touch-recovered').length,sectorHits:bpPoisonLog.filter(e=>e.event==='touch-down'&&e.details?.directionalZone).length},events:bpPoisonLog};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='Block-Party-Gameplay-Diagnostics-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000)};
