  const a=e.details.boundaryAmbiguity;
  counts[a.category]++;
  if(a.distancePx<=20){
   const pair=[e.details.directionalZone,a.alternateDirection].sort().join(' / ');
   pairs[pair]=(pairs[pair]||0)+1;
   if(a.transition?.changed){const t=a.transition.from+' → '+a.transition.to;transitions[t]=(transitions[t]||0)+1;}
  }
  heatmap.push({x:a.normalizedX,y:a.normalizedY,direction:e.details.directionalZone,
   alternate:a.alternateDirection,distancePx:a.distancePx,category:a.category,
   tapId:e.details.tapId});
