 if(window.bpDevActive && /(?:leaderboard|campaign_|power_consume|wallet_spend|wallet_charge|wallet_entry|game_entry|score_submit)/i.test(name) && name!=='bp_developer_authorized' && name!=='bp_campaign_get')throw Error('Developer Mode blocks live write RPC: '+name);
 const r=await fetch(BASE+'/rest/v1/rpc/'+name,{method:'POST',headers:{'apikey':KEY,'Authorization':'Bearer '+auth.access_token,'Content-Type':'application/json'},body:JSON.stringify(params)});
 const raw=await r.text();let data;try{data=JSON.parse(raw)}catch(_){data=raw}
 if(!r.ok)throw Error((data&&data.message)||'Wallet service error '+r.status);
