function checkpointStats(group){
 const first=group*25+1;
 const arr=Array.from({length:25},(_,i)=>Math.max(0,Math.min(3,Number(stars[first+i]||0))));
 const total=arr.reduce((sum,n)=>sum+n,0);
 const counts=[1,2,3].map(tier=>arr.filter(n=>n>=tier).length);
 const qualified=counts[2]===25?40:counts[1]===25?20:counts[0]===25?10:0;
 const nextTier=qualified===0?1:qualified===10?2:qualified===20?3:null;
 const missing=nextTier===null?0:arr.reduce((sum,n)=>sum+Math.max(0,nextTier-n),0);
 return {first,last:first+24,total,counts,qualified,nextTier,missing};
}
function checkpointCard(group){
 const info=checkpointStats(group);
 const card=document.createElement('button');
 card.type='button';
 card.className='bp-checkpoint-inline'+(info.counts[0]===25?' bp-checkpoint-complete':'')+(selectedCheckpoint===group?' bp-checkpoint-selected':'');
 card.setAttribute('aria-label',`View Checkpoint Bonus ${group+1}, ${info.total} of 75 stars, ${info.missing} more for next bonus`);
 card.setAttribute('aria-pressed',String(selectedCheckpoint===group));
 const heading=document.createElement('div');heading.className='bp-checkpoint-inline-title';heading.textContent=`🏁 CHECKPOINT ${group+1}`;
 const subtitle=document.createElement('div');subtitle.className='bp-checkpoint-inline-range';subtitle.textContent=`LEVELS ${info.first}–${info.last}`;
 const starsTotal=document.createElement('div');starsTotal.className='bp-checkpoint-inline-total';starsTotal.textContent=`⭐ ${info.total} / 75 STARS`;
 const next=document.createElement('div');next.className='bp-checkpoint-inline-next';
 next.textContent=info.nextTier===null?'ALL BONUSES EARNED!':`${info.missing} more for next bonus`;
 card.append(heading,subtitle,starsTotal,next);
 card.addEventListener('click',()=>{
  selectedCheckpoint=group;
  gridSelectionClear();
  card.classList.add('bp-checkpoint-selected');
  card.setAttribute('aria-pressed','true');
  detail();
 });
 return card;
}
