// Navigate to meaningful progress rather than resetting to an arbitrary level.
// A locked destination always opens at its first level for preview.
function bpTierDestination(t){
 const first=(t-1)*50+1,last=first+49;
 if(unlocked<first)return first;
 if(unlocked<=last)return unlocked; // Next unlocked level within unfinished tier.
 for(let n=first;n<=last;n++){
  if(Math.max(0,Math.min(3,Number(stars[n]||0)))<3)return n;
 }
 return first; // All levels have three stars.
}
function bpCircuitDestination(c){
 const first=c*150+1,last=first+149;
 if(unlocked<first)return first;
 if(unlocked<=last)return unlocked;
 // Finished circuit: find the earliest level still missing any stars.
 for(let n=first;n<=last;n++){
  if(Math.max(0,Math.min(3,Number(stars[n]||0)))<3)return n;
 }
 return first;
}
function bpCampaignNavigate(n){
 selected=n;selectedCheckpoint=null;
 const grid=$('bpCampaignGrid');if(grid)grid.scrollTop=0;
 render();
}
window.bpCampaignTier=function(t){
 t=Math.max(1,Math.min(6,Number(t)||1));
 if(t===Math.ceil(selected/50))return;
 bpCampaignNavigate(bpTierDestination(t));
};
window.bpCampaignTierStep=function(delta){
 const current=Math.ceil(selected/50),first=current<=3?1:4,last=first+2;
 window.bpCampaignTier(Math.max(first,Math.min(last,current+delta)));
};
window.bpCampaignCircuitStep=function(delta){
 const current=Math.ceil(selected/50),circuit=current<=3?0:1;
 const target=circuit+delta;
 if(target<0||target>1)return;
 bpCampaignNavigate(bpCircuitDestination(target));
};
