async function bpSubmitCampaignSoloLeaderboard(l,result){if(window.bpDevActive)return;
 if(window.bpPowerSession?.assisted||!result.won||!l||!String(l.type).startsWith('solo-'))return;
 const diff=String(l.diff||'').toLowerCase();
 if(!['easy','medium','hard'].includes(diff))return;
 let mode,elapsed=null;
 if(l.type==='solo-line'){
  mode='line';elapsed=Math.round(Number(result.elapsedMs));
  if(!Number.isFinite(elapsed)||elapsed<=0)return;
 }else if(l.type==='solo-timed'){
  const duration=Number(l.duration||180);
  if(![90,180,300].includes(duration))return;
  mode='timed-'+duration;
 }else return;
 const score=Math.floor(Number(result.score));
 if(!Number.isFinite(score)||score<0)return;
 const name=(localStorage.getItem('bp-player-name')||'').trim();
 if(!name||name.length>20)return; // Never submit an unnamed score.
 try{
  await bpRpc('submit_leaderboard_score',{
   p_player_name:name,p_game_mode:mode,p_difficulty:diff,
   p_score:score,p_client_id:bpClientId(),p_duration_ms:elapsed
  });
  bpMiniCache={};
 }catch(e){console.warn('Campaign Solo leaderboard submission failed:',e)}
}
