  const newlyUnlocked=nextAvailable&&unlocked>previouslyUnlocked;
  if(result.won)window.bpShowCampaignStars?.(a.level,earned,nextAvailable,newlyUnlocked);
  const milestoneReward=Math.max(0,Number(d.awarded_tokens)||0);
  if(milestoneReward>0){
   const tier=Number(d.milestone_paid)>=40?3:Number(d.milestone_paid)>=20?2:1;
   setTimeout(()=>window.bpShowMilestoneReward?.(milestoneReward,tier),2600);
  }
