  if(bonusPower){setTimeout(()=>{const names={'double_points':'Double Points','time_extension':'Time Extension','speed_surge':'Speed Surge','special_block_magnet':'Special Block Magnet','garbage_shield':'Garbage Shield','attack_amplifier':'Attack Amplifier','wild_block':'Wild Block','block_bomb':'Block Bomb','board_shuffle':'Board Shuffle'};alert('🎁 SURPRISE POWER-UP!\n'+(names[bonusPower]||bonusPower)+' added to your inventory!');window.bpRefreshTicketStore?.()},3900)}
  const lucky=Number(d.lucky_tickets)||0, checkpointTickets=Number(d.checkpoint_tickets)||0;
